/* ==UserStyle==
@name           Scrollbar page bleu clair sur vert profond
@namespace      userstyles.world
@version        1.0.0
@description    Couleurs de scrollbars sans changer les dimensions
==/UserStyle== */

@-moz-document regexp("(?!https?://([^.]+\\.)?google\\.[a-z.]+/).*") {
  * {
    scrollbar-color: #83c7f6 #0b3d1f !important;
  }

  *::-webkit-scrollbar-track,
  *::-webkit-scrollbar-corner {
    background: #0b3d1f !important;
  }

  *::-webkit-scrollbar-thumb {
    background: #83c7f6 !important;
  }

  *::-webkit-scrollbar-thumb:hover,
  *::-webkit-scrollbar-thumb:active {
    background: #ffffff !important;
  }
}
